<?php
namespace App\Services\Payments;
use App\Contracts\PaymentGatewayInterface;use App\Models\MidtransTransaction;use App\Models\PaymentInvoice;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Log;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
final class SafeLocalPaymentService{public function __construct(private readonly PaymentGatewayInterface $gateway){}public function callback(string $orderId,string $status,?string $transactionId=null,?string $grossAmount=null,?int $invoiceId=null):MidtransTransaction{return DB::transaction(function()use($orderId,$status,$transactionId,$grossAmount,$invoiceId){if(!in_array($status,['pending','paid','failed','expired','cancelled'],true))throw ValidationException::withMessages(['status'=>'Status tidak valid.']);$t=MidtransTransaction::query()->where('order_id',$orderId)->lockForUpdate()->first();if(!$t)throw ValidationException::withMessages(['order_id'=>'Order ID tidak dikenal.']);if($grossAmount!==null&&(float)$grossAmount!==(float)$t->gross_amount)throw ValidationException::withMessages(['gross_amount'=>'Nominal callback tidak cocok.']);if($invoiceId!==null&&(int)$invoiceId!==(int)$t->payment_invoice_id)throw ValidationException::withMessages(['invoice_id'=>'Invoice callback tidak cocok.']);if(in_array($t->transaction_status,['paid','failed','expired','cancelled'],true))return $t;$p=$this->gateway->callback($orderId,$status,$transactionId);$t->fill(['transaction_status'=>$status,'transaction_id'=>$p['transaction_id']??$t->transaction_id,'raw_status_snapshot'=>['source'=>'local_mock','status'=>$status]])->save();Log::info('Local payment status changed',['order_id'=>$orderId,'invoice_id'=>$t->payment_invoice_id,'status'=>$status,'source'=>'local_mock']);return $t->refresh();});}}
